FuncDef.Code:
void opElongate(inout vec3 p, in vec3 elongate)
{
    // TODO: enable this and check/fix all projects
    // This is not strictly necessary, it is here for better compatibility with shadertoy.
    // We have to make sure that parameters for clamp are in correct order (min is smaller than max).
    elongate = abs(elongate);

    // elongate
    p -= clamp( p, -elongate, elongate );
}
